    since(createdAt: number): EventRecord[] { return this.all().filter(event => event.createdAt >= createdAt); }
    count(): number { return this.values.length; }
    latest(): EventRecord | undefined { return this.values[this.values.length - 1]; }
    clear(): void { this.values.length = 0; }
}

