export interface Refund { id: string; amount: Money; reason: string; createdAt: number; }
export interface Order { id: string; memberId: string; lines: OrderLine[]; status: OrderStatus; refunds: Refund[]; internalNotes: string[]; createdAt: number; }

export function createOrder(id: string, memberId: string, createdAt: number): Order {
    return { id, memberId, lines: [], status: 'draft', refunds: [], internalNotes: [], createdAt };
}
export function addLine(order: Order, input: { sku: string; name: string; quantity: number; unitPrice: number | Money }): Order {
    if (!Number.isInteger(input.quantity) || input.quantity <= 0) throw new Error('Quantity must be positive');
    return { ...order, lines: [...order.lines, { ...input, unitPrice: parseMoney(input.unitPrice) }] };
}
export function orderTotal(order: Order): Money {
    return order.lines.reduce((sum, line) => sum.add(line.unitPrice.multiply(line.quantity)), Money.fromCents(0));
}
export function refundTotal(order: Order): Money {
    return order.refunds.reduce((sum, refund) => sum.add(refund.amount), Money.fromCents(0));
}
export function applyRefund(order: Order, refund: Refund): Order {
    const total = orderTotal(order);
    const next = refundTotal(order).add(refund.amount);
    if (next.greaterThan(total)) throw new Error('Refund exceeds order total');
    const status = next.equals(total) ? 'refunded' : 'partially-refunded';
    return { ...order, status, refunds: [...order.refunds, refund] };
}
export function addInternalNote(order: Order, note: string): Order {
    return { ...order, internalNotes: [...order.internalNotes, note] };
}

